-- 0009_content_support (BE-24 step 1): articles, article_attachments, banners, videos, video_schools, notes,
-- perutusan (+ _files, _comments, _reactions, _reads), screenshots, audio_kbat_sets, audio_kbat_attempts,
-- support_config, support_tickets. (0008 is reserved for BE-08 curriculum on another branch.)
-- Generated by Prisma (migrate diff), then edited by hand: identity columns (GENERATED ALWAYS), CHECK
-- constraints (enums are text + check, contract codes), partial index for the open-ticket count.
-- Curriculum ids (videos.subject_id, audio_kbat_sets.education_level_id / subject_id) are FKs to the
-- 0008_curriculum tables (SET NULL on the nullable video subject, RESTRICT on the audio set). Images and attachments are files FKs. Rich-text bodies are
-- sanitised by the service on write. The legacy pair is on articles, banners, videos, notes,
-- audio_kbat_sets and support_tickets (migratable); the other tables have no .cloud source.

-- CreateTable
CREATE TABLE "articles" (
    "id" BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL,
    "title" TEXT NOT NULL,
    "slug" TEXT NOT NULL,
    "excerpt" TEXT,
    "content" TEXT NOT NULL,
    "featured_image_file_id" BIGINT,
    "youtube_url" TEXT,
    "category" TEXT NOT NULL,
    "grade_level" TEXT NOT NULL DEFAULT 'SEMUA',
    "is_published" BOOLEAN NOT NULL DEFAULT false,
    "is_featured" BOOLEAN NOT NULL DEFAULT false,
    "views" INTEGER NOT NULL DEFAULT 0,
    "likes" INTEGER NOT NULL DEFAULT 0,
    "author_id" BIGINT NOT NULL,
    "published_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "legacy_source" TEXT,
    "legacy_id" TEXT,

    CONSTRAINT "articles_pkey" PRIMARY KEY ("id")
);

