-- Enums as text + check (contract codes of @pp/contract).
ALTER TABLE "articles" ADD CONSTRAINT "ck_articles_category" CHECK ("category" IN ('TIPS_BELAJAR', 'BERITA', 'MOTIVASI', 'PANDUAN_IBU_BAPA', 'PANDUAN_GURU', 'KEJAYAAN', 'UMUM'));
ALTER TABLE "articles" ADD CONSTRAINT "ck_articles_grade_level" CHECK ("grade_level" IN ('SEMUA', 'DARJAH_1', 'DARJAH_2', 'DARJAH_3', 'DARJAH_4', 'DARJAH_5', 'DARJAH_6'));
ALTER TABLE "articles" ADD CONSTRAINT "ck_articles_counters" CHECK ("views" >= 0 AND "likes" >= 0);
ALTER TABLE "banners" ADD CONSTRAINT "ck_banners_banner_type" CHECK ("banner_type" IN ('HERO', 'PROMO', 'ANNOUNCEMENT', 'EVENT'));
ALTER TABLE "banners" ADD CONSTRAINT "ck_banners_link_type" CHECK ("link_type" IN ('NONE', 'SUBJECT', 'QUIZ', 'ARTICLE', 'EXTERNAL'));
ALTER TABLE "banners" ADD CONSTRAINT "ck_banners_target_audience" CHECK ("target_audience" IN ('ALL', 'STUDENT', 'TEACHER', 'ADMIN'));
ALTER TABLE "banners" ADD CONSTRAINT "ck_banners_dates" CHECK ("start_date" IS NULL OR "end_date" IS NULL OR "end_date" >= "start_date");
ALTER TABLE "videos" ADD CONSTRAINT "ck_videos_platform" CHECK ("platform" IN ('Youtube', 'Vimeo', 'Dailymotion', 'TikTok', 'Facebook', 'Other'));
ALTER TABLE "videos" ADD CONSTRAINT "ck_videos_category" CHECK ("category" IN ('motivasi', 'tutorial', 'tips-spm', 'ceramah', 'lain-lain'));
ALTER TABLE "videos" ADD CONSTRAINT "ck_videos_visibility" CHECK ("visibility" IN ('global', 'school'));
ALTER TABLE "notes" ADD CONSTRAINT "ck_notes_subject" CHECK ("subject" IN ('matematik', 'sains', 'bahasa_melayu', 'bahasa_inggeris', 'sejarah'));
ALTER TABLE "notes" ADD CONSTRAINT "ck_notes_note_type" CHECK ("note_type" IN ('FORMULA', 'RINGKASAN', 'LENGKAP', 'TIPS_TRICKS', 'MIND_MAP', 'FLASHCARD', 'CHEAT_SHEET'));
ALTER TABLE "perutusan" ADD CONSTRAINT "ck_perutusan_status" CHECK ("status" IN ('published', 'scheduled', 'draft'));
ALTER TABLE "perutusan" ADD CONSTRAINT "ck_perutusan_scope" CHECK ("scope" IN ('national', 'school'));
-- A scheduled message has its publish time. (No check ties scope = school to school_id: the FK is set null on
-- school delete and a check would block that delete; the service validates the pair on write.)
ALTER TABLE "perutusan" ADD CONSTRAINT "ck_perutusan_scheduled" CHECK ("status" <> 'scheduled' OR "scheduled_at" IS NOT NULL);
ALTER TABLE "perutusan_files" ADD CONSTRAINT "ck_perutusan_files_kind" CHECK ("kind" IN ('image', 'document'));
ALTER TABLE "perutusan_comments" ADD CONSTRAINT "ck_perutusan_comments_status" CHECK ("status" IN ('pending', 'approved', 'rejected'));
ALTER TABLE "perutusan_reactions" ADD CONSTRAINT "ck_perutusan_reactions_kind" CHECK ("kind" IN ('like', 'love', 'thanks'));
ALTER TABLE "audio_kbat_sets" ADD CONSTRAINT "ck_audio_kbat_sets_status" CHECK ("status" IN ('draft', 'pending_review', 'approved', 'archived'));
ALTER TABLE "audio_kbat_sets" ADD CONSTRAINT "ck_audio_kbat_sets_documents" CHECK (jsonb_typeof("sections") = 'array' AND jsonb_typeof("questions") = 'array');
ALTER TABLE "audio_kbat_attempts" ADD CONSTRAINT "ck_audio_kbat_attempts_answers" CHECK (jsonb_typeof("answers") = 'array');
ALTER TABLE "audio_kbat_attempts" ADD CONSTRAINT "ck_audio_kbat_attempts_score" CHECK ("score" >= 0 AND "total_marks" >= 0 AND "score" <= "total_marks");
ALTER TABLE "support_config" ADD CONSTRAINT "ck_support_config_singleton" CHECK ("id" = 1);
ALTER TABLE "support_tickets" ADD CONSTRAINT "ck_support_tickets_status" CHECK ("status" IN ('dibuka', 'dalam_proses', 'menunggu_balas', 'selesai', 'ditutup'));
ALTER TABLE "support_tickets" ADD CONSTRAINT "ck_support_tickets_subject" CHECK (char_length("subject") BETWEEN 1 AND 255);

-- BE-24: section audio of Audio KBAT sets is stored in files (purpose audio_kbat). Widen the mime list of
-- 0005_files with the four audio types and image/gif (perutusan images; no files purpose accepts gif for upload). Reversible: put the 0005 list back
-- once no audio row exists.
ALTER TABLE "files" DROP CONSTRAINT "ck_files_mime";
ALTER TABLE "files" ADD CONSTRAINT "ck_files_mime" CHECK ("mime" IN ('image/jpeg', 'image/png', 'image/webp', 'application/pdf', 'image/gif', 'audio/mpeg', 'audio/mp4', 'audio/wav', 'audio/ogg'));
